/**
 * @file fake_sdk.h
 * @brief Fake pico-sdk for PC-side tests: the SDK functions and types the
 *        Phyduino core, variant and libraries use, backed by simulated
 *        hardware state in `fake::hw` that tests can inspect and drive.
 *
 * Every SDK header the code includes ("hardware/gpio.h", "pico/time.h", ...)
 * is generated by tests/host/CMakeLists.txt as a one-line include of this file.
 * Only behaviour the tests need is simulated; extend it as tests grow.
 */
#pragma once

#include <cstddef>
#include <cstdint>
#include <deque>
#include <functional>
#include <string>
#include <vector>

typedef unsigned int uint;

// --- Constants -----------------------------------------------------------------
#define NUM_BANK0_GPIOS 30
#define PICO_ERROR_NONE     0
#define PICO_ERROR_TIMEOUT  (-1)
#define PICO_ERROR_GENERIC  (-2)
#define PICO_LOWEST_IRQ_PRIORITY 0xFF
#define UART0_IRQ 20
#define UART1_IRQ 21
#define DREQ_SPI0_TX 16
#define DREQ_ADC 36

enum gpio_function_t {
    GPIO_FUNC_SPI = 1, GPIO_FUNC_UART = 2, GPIO_FUNC_I2C = 3, GPIO_FUNC_PWM = 4,
    GPIO_FUNC_SIO = 5, GPIO_FUNC_NULL = 0x1F,
};
enum { GPIO_IN = 0, GPIO_OUT = 1 };
enum gpio_irq_level {
    GPIO_IRQ_LEVEL_LOW = 0x1, GPIO_IRQ_LEVEL_HIGH = 0x2,
    GPIO_IRQ_EDGE_FALL = 0x4, GPIO_IRQ_EDGE_RISE = 0x8,
};
enum gpio_drive_strength {
    GPIO_DRIVE_STRENGTH_2MA, GPIO_DRIVE_STRENGTH_4MA,
    GPIO_DRIVE_STRENGTH_8MA, GPIO_DRIVE_STRENGTH_12MA,
};
typedef enum { UART_PARITY_NONE, UART_PARITY_EVEN, UART_PARITY_ODD } uart_parity_t;
typedef enum { SPI_CPOL_0, SPI_CPOL_1 } spi_cpol_t;
typedef enum { SPI_CPHA_0, SPI_CPHA_1 } spi_cpha_t;
typedef enum { SPI_LSB_FIRST, SPI_MSB_FIRST } spi_order_t;
typedef enum { I2C_SLAVE_RECEIVE, I2C_SLAVE_REQUEST, I2C_SLAVE_FINISH } i2c_slave_event_t;
enum clock_index { clk_sys = 5 };

// --- Peripheral instances ----------------------------------------------------------
struct uart_inst { int index; };
struct spi_inst  { int index; };
struct i2c_inst  { int index; };
typedef uart_inst uart_inst_t;
typedef spi_inst  spi_inst_t;
typedef i2c_inst  i2c_inst_t;

namespace fake {
extern uart_inst_t uart_instances[2];
extern spi_inst_t  spi_instances[2];
extern i2c_inst_t  i2c_instances[2];
}
#define uart0 (&fake::uart_instances[0])
#define uart1 (&fake::uart_instances[1])
#define spi0  (&fake::spi_instances[0])
#define spi1  (&fake::spi_instances[1])
#define i2c0  (&fake::i2c_instances[0])
#define i2c1  (&fake::i2c_instances[1])

typedef void (*irq_handler_t)();
typedef void (*gpio_irq_callback_t)(uint gpio, uint32_t events);
typedef void (*i2c_slave_handler_t)(i2c_inst_t*, i2c_slave_event_t);
typedef int32_t alarm_id_t;
typedef int64_t (*alarm_callback_t)(alarm_id_t, void*);

// --- Simulated hardware --------------------------------------------------------------
namespace fake {

struct Gpio {
    uint function = GPIO_FUNC_NULL;
    bool initialised = false;   // gpio_init() called
    bool output = false;        // direction
    bool out_level = false;     // output latch
    bool pull_up = false;
    bool pull_down = false;
    int drive = GPIO_DRIVE_STRENGTH_4MA;
    uint32_t irq_events = 0;    // enabled IRQ events
    bool input_level = false;   // what gpio_get() returns when not driven
    // Optional: input level as a function of time (for pulseIn etc.).
    std::function<bool(uint64_t now_us)> waveform;
};

struct PwmSlice {
    uint div_int = 1;
    uint wrap = 0xFFFF;
    bool enabled = false;
    uint16_t level[2] = {0, 0};  // channel A (even GPIO), B (odd GPIO)
};

struct Uart {
    bool enabled = false;
    uint baud = 0;
    uint data_bits = 8, stop_bits = 1;
    uart_parity_t parity = UART_PARITY_NONE;
    bool rx_irq = false;
    std::string tx;              // bytes written
    std::deque<uint8_t> rx;      // bytes waiting to be received
};

struct Spi {
    bool enabled = false;
    uint baud = 0;
    spi_cpol_t cpol = SPI_CPOL_0;
    spi_cpha_t cpha = SPI_CPHA_0;
    uint data_bits = 8;
    std::vector<uint8_t> sent;   // every byte clocked out
    // Byte clocked in for each byte clocked out. Default: returns 0.
    std::function<uint8_t(uint8_t out)> device;
};

struct I2c {
    bool enabled = false;
    uint baud = 0;
    // Controller transfers; return bytes transferred or PICO_ERROR_*.
    // Default: no device answers (PICO_ERROR_GENERIC).
    std::function<int(uint8_t addr, const uint8_t* data, size_t len, bool nostop)> on_write;
    std::function<int(uint8_t addr, uint8_t* data, size_t len, bool nostop)> on_read;
    // Peripheral (slave) mode
    i2c_slave_handler_t slave_handler = nullptr;
    uint8_t slave_address = 0;
    std::deque<uint8_t> slave_rx;     // bytes the "controller" wrote
    std::vector<uint8_t> slave_tx;    // bytes we sent back
};

struct Alarm {
    alarm_id_t id;
    uint64_t at_us;
    alarm_callback_t callback;
    void* data;
};

struct DmaChannel {
    bool claimed = false;
    bool started = false;
    bool done = false;
    uint dreq = 0;
    bool read_increment = true;
    bool write_increment = false;
    volatile void* write = nullptr;
    const volatile void* read = nullptr;
    uint32_t count = 0;
};

struct Hardware {
    Gpio gpio[NUM_BANK0_GPIOS];
    bool adc_initialised = false;
    uint adc_selected = 0;
    uint16_t adc_values[5] = {0, 0, 0, 0, 0};   // 12-bit, per ADC input
    // Optional: value of each ADC conversion (overrides adc_values), e.g. a ramp.
    std::function<uint16_t(uint input)> adc_sample;
    uint32_t adc_conversions = 0;   // adc_read() calls plus DMA samples
    bool adc_fifo_enabled = false;
    bool adc_fifo_dreq = false;
    float adc_clkdiv = 0;
    float adc_clkdiv_at_run = 0;    // divider when adc_run(true) was last called
    bool adc_running = false;
    DmaChannel dma[12];
    // DMA transfers finish this many dma_channel_is_busy() polls after starting.
    int dma_busy_polls = 0;
    PwmSlice pwm[8];
    Uart uart[2];
    Spi spi[2];
    I2c i2c[2];
    uint32_t sys_hz = 125000000;
    uint64_t now_us = 0;
    uint32_t us_per_time_read = 1;  // time moves on each time_us_*() read, so busy-waits end
    std::vector<Alarm> alarms;
    alarm_id_t next_alarm_id = 1;
    bool in_alarm = false;          // alarms do not nest, like interrupts of one priority
    irq_handler_t irq_handlers[32] = {};
    bool irq_enabled[32] = {};
    gpio_irq_callback_t gpio_callback = nullptr;
    int interrupts_disabled = 0;
    // Called on every gpio_put(), after the latch changes (chip models hook in here).
    std::function<void(uint gpio, bool value)> on_gpio_put;
};

extern Hardware hw;

/// Back to power-on state. Called before every test (test_main.cpp).
void reset();
/// Moves time forward, running alarms that fall due.
void advance_us(uint64_t us);
/// Runs the IRQ handler registered for `irq` (e.g. UART0_IRQ).
void raise_irq(uint irq);
/// Simulates a GPIO interrupt event on `gpio` if that event is enabled.
void trigger_gpio_irq(uint gpio, uint32_t events);
/// Level gpio_get() would read now.
bool pin_level(uint gpio);

}  // namespace fake

// --- pico/time.h -----------------------------------------------------------------
uint64_t time_us_64();
uint32_t time_us_32();
void sleep_ms(uint32_t ms);
void sleep_us(uint64_t us);
void busy_wait_us_32(uint32_t us);
void busy_wait_at_least_cycles(uint32_t cycles);
alarm_id_t add_alarm_in_ms(uint32_t ms, alarm_callback_t callback, void* data, bool fire_if_past);
alarm_id_t add_alarm_in_us(uint64_t us, alarm_callback_t callback, void* data, bool fire_if_past);
bool cancel_alarm(alarm_id_t id);
struct repeating_timer;
typedef struct repeating_timer repeating_timer_t;
typedef bool (*repeating_timer_callback_t)(repeating_timer_t* rt);
struct repeating_timer {
    int64_t delay_us;
    repeating_timer_callback_t callback;
    void* user_data;
    alarm_id_t alarm_id;
};
bool add_repeating_timer_us(int64_t delay_us, repeating_timer_callback_t callback, void* user_data,
                            repeating_timer_t* out);
bool cancel_repeating_timer(repeating_timer_t* timer);

